function CoinChange(coins: int[], amount: int) -> int {
  // Return the fewest coins summing to amount, or -1 if impossible.
  return -1;
}

solution:
function CoinChange(coins: int[], amount: int) -> int {
  let big = amount + 1;
  let dp: int[] = [];
  let i = 0;
  while (i <= amount) {
    dp.push(big);
    i += 1;
  }
  dp[0] = 0;
  let a = 1;
  while (a <= amount) {
    let c = 0;
    while (c < coins.length()) {
      let coin = coins[c];
      if (coin <= a) {
        let sub = dp[a - coin];
        if (sub + 1 < dp[a]) {
          dp[a] = sub + 1;
        }
      }
      c += 1;
    }
    a += 1;
  }
  if (dp[amount] > amount) {
    return -1;
  }
  return dp[amount];
}
